graphql.query:
query GetPastLaunches($limit: Int!) {
  launchesPast(limit: $limit) {
    id
    mission_name
    launch_date_local
    launch_site {
      site_name_long
    }
    rocket {
      rocket_name
      rocket_type
    }
    ships {
      name
      home_port
    }
    links {
      article_link
      video_link
    }
  }
}

query GetLaunch($id: ID!) {
  launch(id: $id) {
    id
    mission_name
    details
    launch_date_local
    launch_success
    launch_site {
      site_name
      site_name_long
    }
    rocket {
      rocket_name
      rocket_type
      rocket {
        company
        country
        description
      }
    }
    links {
      article_link
      video_link
      flickr_images
    }
  }
}

query SearchLaunches($missionName: String!) {
  launches(find: {mission_name: $missionName}) {
    id
    mission_name
    details
    launch_date_local
    launch_success
    rocket {
      rocket_name
    }
    links {
      article_link
      video_link
    }
  }
}

query {
  launchesUpcoming(limit: 5) {
    id
    mission_name
    launch_date_local
    launch_site {
      site_name_long
    }
    rocket {
      rocket_name
    }
    links {
      article_link
      video_link
    }
  }
}

query GetRockets {
  rockets {
    id
    name
    type
    active
    country
    company
    description
    first_flight
    success_rate_pct
    cost_per_launch
    height {
      meters
      feet
    }
    diameter {
      meters
      feet
    }
    mass {
      kg
      lb
    }
  }
}

query GetMissionAndRocket($missionName: String!, $rocketId: ID!) {
  launches(find: {mission_name: $missionName}) {
    mission_name
    launch_date_local
    launch_success
    details
  }
  rocket(id: $rocketId) {
    name
    type
    description
    success_rate_pct
  }
}

query {
  company {
    name
    founder
    founded
    summary
  }
  launchesPast(limit: 3) {
    mission_name
    launch_date_local
    launch_success
  }
